def transform(grid):
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    # collect diamonds: 2-cells, group into diamonds of 4 via bounding boxes 3x3
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2]
    un=set(cells); dia=[]
    while un:
        r,c=un.pop()
        # diamond top tip at (r,c)? try four orientations
        for dr,dc in [(0,0)]:
            pass
        found=None
        for tr,tc in [(r,c),(r,c-1),(r,c-2),(r-1,c),(r-2,c),(r-1,c-1),(r-2,c-1),(r-1,c-2),(r-2,c-2)]:
            box={(tr,tc),(tr+1,tc-1),(tr+1,tc+1),(tr+2,tc)}
            if box<=un and (tr,tc) in {(r,c)}|un:
                # ensure (r,c) in box
                if (r,c) in box and box<=un:
                    found=box; break
        if not found:  # fallback: singleton
            found={(r,c)}
        un-=found
        cr=tr+1; cc=tc
        dia.append((cr,cc,found))
    for i in range(len(dia)):
        for j in range(i+1,len(dia)):
            r1,c1,b1=dia[i]; r2,c2,b2=dia[j]
            if r1==r2:
                a,b=min(c1,c2),max(c1,c2)
                for c in range(a+1,b):
                    if g[r1][c]==0: g[r1][c]=1
            if c1==c2:
                a,b=min(r1,r2),max(r1,r2)
                for r in range(a+1,b):
                    if g[r][c1]==0: g[r][c1]=1
    return g

